import { motion, useScroll, useTransform } from 'framer-motion';
import { useRef } from 'react';
import { Play, ArrowDown } from 'lucide-react';
import { RevealLines } from './Reveal';
import { HERO } from '@/constants/testIds/portfolio';
import { CHANNEL_URL } from '@/data/films';

const HERO_IMG =
  'https://images.pexels.com/photos/23384400/pexels-photo-23384400.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=1200&w=1600';

export const Hero = ({ onWatchReel }) => {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ['start start', 'end start'] });
  const y = useTransform(scrollYProgress, [0, 1], ['0%', '25%']);
  const scale = useTransform(scrollYProgress, [0, 1], [1, 1.15]);
  const opacity = useTransform(scrollYProgress, [0, 0.8], [1, 0]);

  return (
    <section
      id="top"
      ref={ref}
      data-testid={HERO.section}
      className="relative min-h-screen w-full overflow-hidden vignette"
    >
      <motion.div style={{ y, scale }} className="absolute inset-0 z-0">
        <img src={HERO_IMG} alt="Cinematographer at work" className="w-full h-full object-cover" />
        <div className="absolute inset-0 bg-black/60" />
        <div className="absolute inset-0 bg-gradient-to-t from-[#050505] via-transparent to-[#050505]/40" />
      </motion.div>

      <motion.div style={{ opacity }} className="relative z-10 min-h-screen flex flex-col justify-between px-6 md:px-12 pt-32 pb-12">
        {/* top meta row */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1.1, duration: 1 }}
          className="flex justify-between items-start text-[11px] tracking-[0.25em] uppercase text-white/60"
        >
          <span>Tamil Cinema / Est. 2023</span>
          <span className="hidden md:block max-w-[200px] text-right leading-relaxed">
            28+ Short Films — Written, Shot & Directed independently
          </span>
        </motion.div>

        {/* headline */}
        <div className="max-w-[1100px]">
          <div className="overflow-hidden mb-4">
            <motion.span
              initial={{ y: '110%' }}
              animate={{ y: 0 }}
              transition={{ delay: 0.5, duration: 0.9, ease: [0.16, 1, 0.3, 1] }}
              className="block font-serif-italic text-[#E11D48] text-2xl md:text-4xl"
            >
              We make small films that hit hard.
            </motion.span>
          </div>
          <h1 className="font-display font-semibold leading-[0.92] text-[15vw] md:text-[11vw] lg:text-[9.5rem] uppercase">
            <RevealLines lines={['Stupid', 'Studios']} delay={0.6} />
          </h1>
        </div>

        {/* bottom row */}
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 1.2, duration: 0.9 }}
            className="max-w-md text-sm md:text-base text-white/70 leading-relaxed"
          >
            An independent Tamil short-film collective crafting thrillers, romance and comedy —
            one frame, one story at a time.
          </motion.p>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 1.35, duration: 0.9 }}
            className="flex items-center gap-5"
          >
            <button
              onClick={onWatchReel}
              data-testid={HERO.watchReel}
              className="group flex items-center gap-3 bg-white text-black rounded-full pl-2 pr-6 py-2 hover:bg-[#E11D48] hover:text-white transition-colors duration-300"
            >
              <span className="flex items-center justify-center w-10 h-10 rounded-full bg-black text-white group-hover:bg-white group-hover:text-[#E11D48] transition-colors duration-300">
                <Play className="w-4 h-4 fill-current ml-0.5" />
              </span>
              <span className="text-xs tracking-[0.2em] uppercase font-medium">Watch Latest</span>
            </button>
            <a
              href={CHANNEL_URL}
              target="_blank"
              rel="noopener noreferrer"
              className="text-xs tracking-[0.2em] uppercase text-white/60 hover:text-white transition-colors duration-300 border-b border-white/20 pb-1"
            >
              YouTube ↗
            </a>
          </motion.div>
        </div>
      </motion.div>

      <motion.div
        style={{ opacity }}
        animate={{ y: [0, 10, 0] }}
        transition={{ repeat: Infinity, duration: 2 }}
        data-testid={HERO.scrollCue}
        className="absolute bottom-6 left-1/2 -translate-x-1/2 z-10 text-white/40"
      >
        <ArrowDown className="w-5 h-5" />
      </motion.div>
    </section>
  );
};
